import { forwardRef } from "react";
import type { SVGProps } from "react";

/**
 * Real brand logo marks, vector-traced from the brand guide PDF (the
 * cleaned source SVGs live in public/brand/ -- see
 * brand/BRAND_REFERENCE.md Gap 6 for the full story). Every mark is
 * single-color artwork rendered with fill="currentColor", so `tone` is
 * just a CSS color swap (text-tf-black / text-tf-white) -- one shape per
 * mark, no separate positive/negative files needed.
 *
 * These are traced (pdftocairo -svg doesn't honor pixel crop options, so
 * isolating a specific path group straight from the page wasn't
 * available -- bitmap-crop-then-vtracer-trace was the practical
 * alternative) rather than the actual licensed vector source files. Swap
 * in real vectors from the brand asset folder when available; every mark
 * keeps this same component API so callers don't need to change.
 *
 * Sizing: pass `width` or `height` (in px) to fix that dimension via
 * inline style -- the other follows the mark's real aspect ratio
 * automatically, and gets checked in dev against this mark's brand-guide
 * minimum. Pass neither and size purely via `className` (e.g. Tailwind's
 * `h-16 w-auto sm:h-20`) for responsive/breakpoint-driven sizing instead
 * -- the dev-mode minimum check is skipped in that case since there's no
 * single rendered size to compare.
 */

export type LogoTone = "positive" | "negative";

const TONE_CLASS: Record<LogoTone, string> = {
  positive: "text-tf-black",
  negative: "text-tf-white",
};

export interface MarkProps
  extends Omit<SVGProps<SVGSVGElement>, "width" | "height" | "className"> {
  tone?: LogoTone;
  className?: string;
  width?: number;
  height?: number;
  /** Accessible name. Omit for decorative use (gets aria-hidden). */
  title?: string;
}

function warnIfBelowMinimum(
  name: string,
  px: number,
  minPx: number,
  dimension: "width" | "height"
) {
  if (process.env.NODE_ENV !== "production" && px < minPx) {
    console.warn(
      `[${name}] rendered at ${Math.round(px)}px ${dimension}, below the brand guide's ${minPx}px minimum for this mark.`
    );
  }
}

interface ResolvedMarkProps {
  className: string;
  style?: { width?: number; height?: number };
  accessibility: { role: "img"; "aria-label": string } | { "aria-hidden": true };
  rest: Omit<MarkProps, "tone" | "className" | "title" | "width" | "height">;
  resolvedWidth?: number;
  resolvedHeight?: number;
}

function resolveMarkProps(
  { tone = "positive", className = "", title, width, height, ...rest }: MarkProps,
  viewW: number,
  viewH: number
): ResolvedMarkProps {
  const aspect = viewW / viewH;
  const resolvedWidth = width ?? (height !== undefined ? height * aspect : undefined);
  const resolvedHeight = height ?? (width !== undefined ? width / aspect : undefined);
  return {
    className: `${TONE_CLASS[tone]} ${className}`,
    style:
      resolvedWidth !== undefined || resolvedHeight !== undefined
        ? { width: resolvedWidth, height: resolvedHeight }
        : undefined,
    accessibility: title ? { role: "img", "aria-label": title } : { "aria-hidden": true },
    rest,
    resolvedWidth,
    resolvedHeight,
  };
}

